 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    counts = {}
    for row in grid:
        for v in row:
            counts[v] = counts.get(v, 0) + 1
    bg = max(counts, key=counts.get)

    # A solid full-width or full-height line is the divider.
    divider = None
    for r in range(h):
        if len(set(grid[r])) == 1 and grid[r][0] != bg:
            divider = ('h', r, grid[r][0])
            break
    if divider is None:
        for c in range(w):
            vals = {grid[r][c] for r in range(h)}
            if len(vals) == 1 and next(iter(vals)) != bg:
                divider = ('v', c, grid[0][c])
                break
    if divider is None:
        return [row[:] for row in grid]

    orient, pos, divider_color = divider
    object_colors = [c for c in counts if c != bg and c != divider_color]
    if not object_colors:
        return [row[:] for row in grid]
    obj_color = object_colors[0]
    coords = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == obj_color]
    if not coords:
        return [row[:] for row in grid]
    out = [row[:] for row in grid]

    if orient == 'h':
        rows = [r for r, c in coords]
        if min(rows) > pos:
            shift = pos + 1 - min(rows)  # slide toward divider from below
            coords = [(r + shift, c) for r, c in coords]
            marker = max(r for r, c in coords) + 1
            if 0 <= marker < h:
                out[marker] = [8] * w
        else:
            shift = pos - 1 - max(rows)  # slide toward divider from above
            coords = [(r + shift, c) for r, c in coords]
            marker = min(r for r, c in coords) - 1
            if 0 <= marker < h:
                out[marker] = [8] * w
    else:
        cols = [c for r, c in coords]
        if min(cols) > pos:
            shift = pos + 1 - min(cols)
            coords = [(r, c + shift) for r, c in coords]
            marker = max(c for r, c in coords) + 1
            if 0 <= marker < w:
                for r in range(h):
                    out[r][marker] = 8
        else:
            shift = pos - 1 - max(cols)
            coords = [(r, c + shift) for r, c in coords]
            marker = min(c for r, c in coords) - 1
            if 0 <= marker < w:
                for r in range(h):
                    out[r][marker] = 8

    # Move the colored object into contact with the divider and mark its far side.
    for r, c in [(r, c) for r in range(h) for c in range(w) if grid[r][c] == obj_color]:
        out[r][c] = bg
    for r, c in coords:
        out[r][c] = obj_color
    return out
